        """Perform exponentiation operation"""
        return base ** exponent

    def _perform_multiplication_operation(left, right):
        """Perform multiplication operation"""
        return left * right

    def _perform_floor_division_operation(left, right):
        """Perform floor division operation"""
        return left // right

