        """Execute a single operation based on operator type"""
        if operator == '**':
            return _perform_exponentiation_operation(left_operand, right_operand)
        elif operator == '*':
            return _perform_multiplication_operation(left_operand, right_operand)
        elif operator == '//':
            return _perform_floor_division_operation(left_operand, right_operand)
        elif operator == '+':
            return _perform_addition_operation(left_operand, right_operand)
        elif operator == '-':
            return _perform_subtraction_operation(left_operand, right_operand)

